			"eventHandlers": [
				{
					"type": "drilldown.linkToSearch",
					"options": {
						"type": "custom",
						"query": "index=corelight sourcetype=corelight_detections\n| fields sid, uids, did, suri_ids{}, seen{},attack_phase, category, hash, impact_score, impact_score_reason, signature, suri_id_count, technique_number, technique_name, is_dest_internal_ip, is_src_internal_ip, sensor_name, answers, category, cert_chain_fps, client_headers, cve_creation_date, cve_description, cve_exploitability_score, cve_impact_score, cve_number, did, filename, host, id.orig_h, id.orig_p, id.resp_h, id.resp_p, issuer, md5, method, mime_type, qtype_name, rcode_name, rx_host, seen, seen_bytes, server_name, sha256, sid, signature, status_code, sub_technique_name, sub_technique_number, subject, suri_id, suri_rule, traffic_direction, ts, uids, uri, user_agent, validation_status | dedup sid\n| where is_dest_internal_ip = \"true\"",
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$",
						"newTab": true
					}
				}
			]
		},
