					},
					"ids": {
						"width": 30
					},
					"DID": {
						"width": 131,
						"data": "> table | seriesByName(\"DID\") | formatByType(DIDColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"DID\") | matchValue(DIDRowColorsEditorConfig)"
					},
